  case wasm_verdict do
    :ok ->
      excluded

    {:unavailable, reason} ->
      IO.puts(:stderr, "[wasm] EXCLUDING :wasm -- " <> reason)
      [:wasm | excluded]
  end

# Composition tests tagged `:ash_graphql` / `:ash_json_api` exercise REAL
