optional_extensions = [
  {:ash_graphql, AshGraphql.Resource},
  {:ash_json_api, AshJsonApi.Resource}
]

excluded =
  Enum.reduce(optional_extensions, excluded, fn {tag, module}, acc ->
    case Code.ensure_loaded(module) do
      {:module, _} ->
